def solve(payload):
    used, pairs = set(), []
    for left in sorted(payload['left']):
        candidates = sorted({b for a, b in payload['edges'] if a == left and b not in used})
        if candidates:
            used.add(candidates[0])
            pairs.append([left, candidates[0]])
    return {'size': len(pairs), 'pairs': pairs}

