# SPDX-License-Identifier: AGPL-3.0-only
from functools import lru_cache

def solve(payload):
    left = sorted(payload['left'])
    right = sorted(payload['right'])
    positions = {name: i for i, name in enumerate(right)}
    neighbors = {name: set() for name in left}
    for a, b in payload['edges']:
        neighbors[a].add(b)
    @lru_cache(None)
    def best(index, used):
        if index == len(left):
            return ()
        choices = [best(index + 1, used)]
        for target in sorted(neighbors[left[index]]):
            bit = 1 << positions[target]
            if not used & bit:
                choices.append(((left[index], target),) + best(index + 1, used | bit))
        return min(choices, key=lambda pairs: (-len(pairs), pairs))
    pairs = best(0, 0)
    return {'size': len(pairs), 'pairs': [list(pair) for pair in pairs]}

